import tomllib
from pprint import pprint

def md_to_toml(text):
    out, in_fence = [], False
    for line in text.splitlines():
        s = line.strip()
        if not in_fence and s.startswith("```toml"):
            in_fence = True; out.append("")
        elif in_fence and s == "```":
            in_fence = False; out.append("")
        else:
            out.append(line if in_fence else "")
    if in_fence: raise ValueError("unclosed toml fence")
    return "\n".join(out)

results = {}
for name in ("test2-vc-config.md", "test3-vc-config.md"):
    text = open(name).read()
    results[name] = tomllib.loads(md_to_toml(text))
    print(f"--- {name} ---")
    pprint(results[name])
print("identical:", results["test2-vc-config.md"] == results["test3-vc-config.md"])
EOF

