667	/// True when `dir` is a workspace's bot repo.
668	///
669	/// Side detection is by *self-resolution*: `dir` is the bot side
670	/// iff its own `.vc-config.toml`'s `repos.bot` resolves
671	/// (file-relative) back to `dir` itself: the entry that names the
672	/// config's own directory names the side. Falls back to the
673	/// legacy location rule ([`legacy_is_bot_dir`]) so read-only
674	/// surfaces that bypass the resolvers' legacy rejection (explicit
675	/// `--other-repo` paths in validate-desc / fix-desc) still see a
676	/// legacy bot dir as the bot side. Paths are canonicalized so
677	/// relative forms and symlinked tempdirs compare correctly;
678	/// anything unreadable is "not the bot side".
679	pub fn is_bot_dir(dir: &Path) -> bool {
680	    let Ok(dir) = dir.canonicalize() else {
681	        return false;
682	    };
683	    if let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE))
684	        && let Some(bot) = toml_simple::toml_get(&cfg, "repos.bot").filter(|v| !v.is_empty())
685	    {
686	        return resolve_repo_path(&dir, bot)
687	            .canonicalize()
688	            .is_ok_and(|p| p == dir);
689	    }
690	    crate::legacy_vc_config::is_bot_dir(&dir)
691	}
692	
693	/// Walk up from `start` to find the workspace root (the work repo).
694	///
695	/// The nearest ancestor with a `.vc-config.toml` decides: its
696	/// `repos.work`, resolved file-relative, *is* the root: the walk
697	/// finding the bot repo's config first still lands on the work
698	/// repo (its `work` points there), so the two sides need no
699	/// nesting assumption. Returns `None` if no config is found up to
700	/// the filesystem root: the caller is in a "plain old repo" (POR)
701	/// with no vc-x1 workspace metadata.
702	///
703	/// Legacy roots (the 0.75.x root-anchored `[workspace] work`
704	/// schema and the pre-0.75.0 `path = "/"` schema) are still
705	/// *found* (pointed at the work side via the legacy location
706	/// rule), so the resolvers can reject them with a fix-it message
707	/// via `reject_legacy_config` instead of silently degrading the
708	/// workspace to POR.
709	pub fn find_workspace_root_from(start: &Path) -> Option<PathBuf> {
710	    let mut cur = start.to_path_buf();
711	    loop {
712	        let cfg = cur.join(VC_CONFIG_FILE);
713	        if let Ok(map) = toml_simple::toml_load(&cfg) {
714	            if let Some(work) = toml_simple::toml_get(&map, "repos.work") {
715	                let resolved = resolve_repo_path(&cur, work);
716	                // OK: a declared-but-missing work dir surfaces at
717	                // the resolvers' coherence checks, not here.
718	                return Some(resolved.canonicalize().unwrap_or(resolved));
719	            }
720	            if crate::legacy_vc_config::is_root_marker(&map) {
721	                return if crate::legacy_vc_config::is_bot_dir(&cur) {
722	                    cur.parent().map(Path::to_path_buf)
723	                } else {
724	                    Some(cur)
725	                };
726	            }
727	        }
728	        cur = cur.parent()?.to_path_buf();
729	    }
730	}
731	
732	/// Error fast on a legacy `.vc-config.toml` schema.
733	///
734	/// The topology readers treat unknown keys as absent, which would
735	/// silently degrade a dual workspace to single-repo, so every
736	/// resolver calls this first and fails with the
737	/// [`legacy_vc_config::reject`](crate::legacy_vc_config::reject)
738	/// rewrite instead. A config with both a `[repos]` registry and
739	/// stray legacy keys passes (the registry drives behavior;
740	/// `config --validate` flags the strays). Also rejects an empty
741	/// `repos.work`: every reader would silently misresolve it.
742	pub fn reject_legacy_config(dir: &Path) -> Result<(), Box<dyn std::error::Error>> {
743	    let Ok(cfg) = toml_simple::toml_load(&dir.join(VC_CONFIG_FILE)) else {
744	        return Ok(());
745	    };
746	    if let Some(msg) = crate::legacy_vc_config::reject(dir, &cfg) {
747	        return Err(msg.into());
748	    }
749	    if toml_simple::toml_get(&cfg, "repos.work").is_some_and(|w| w.is_empty()) {
750	        return Err(format!(
751	            "{}/.vc-config.toml: repos.work is empty: it must be a path \
752	             (relative to the config file's directory, e.g. \".\" in the \
753	             work repo); nothing was changed",
754	            dir.display()
755	        )
756	        .into());
757	    }
758	    Ok(())
759	}
760	
761	/// Cwd-anchored wrapper over [`find_workspace_root_from`].
762	pub fn find_workspace_root() -> Option<PathBuf> {
763	    let cur = std::env::current_dir().ok()?;
764	    find_workspace_root_from(&cur)
765	}
766	
767	/// Resolve the workspace's default `--scope`.
768	///
769	/// Reads `<workspace_root>/.vc-config.toml > repos.bot`:
770	///
771	/// - dual workspace (non-empty `bot`) -> `Scope([Work, Bot])`
772	/// - single-repo workspace (missing / empty `bot`) ->
773	///   `Scope([Work])`
774	/// - POR (no `workspace_root`) -> `Scope([Work])`: `scope_to_repos`
775	///   resolves `Side::Work` to cwd's `.` when no root is given, so a
776	///   POR run still operates on the current directory.
777	pub fn default_scope(workspace_root: Option<&Path>) -> Scope {
778	    let Some(root) = workspace_root else {
779	        return Scope(vec![Side::Work]);
780	    };
781	    let cfg = match toml_simple::toml_load(&root.join(VC_CONFIG_FILE)) {
782	        Ok(c) => c,
783	        Err(_) => return Scope(vec![Side::Work]),
784	    };
785	    match toml_simple::toml_get(&cfg, "repos.bot") {
786	        Some(v) if !v.is_empty() => Scope(vec![Side::Work, Side::Bot]),
787	        _ => Scope(vec![Side::Work]),
788	    }
789	}

