1	//! The `config` subcommand: print the settable config schema for a
2	//! target config file (or check it with `--validate`), grouped by
3	//! TOML section, sshd_config style.
4	//!
5	//! - Read-only; consumes `crate::config_schema::schema()`: the
6	//!   single source of truth for every settable key.
7	//! - The positional target is `work`, `bot`, `work,bot` (default),
8	//!   or an explicit config-file path. The user config
9	//!   (`~/.config/vc-x1/config.toml`) has no keyword: reach it by
10	//!   passing its path.
11	//! - The side keywords filter to that side's keys; a path target
12	//!   carries no side information, so it gets the whole schema: no
13	//!   guessing what kind of file the path names.
14	//! - `--validate` checks the target file(s) instead of printing:
15	//!   unknown keys, and (for keyword targets) the legacy-schema
16	//!   rejection plus the resolved-agreement invariant of a dual
17	//!   workspace's `[repos]` registries (via the bot-side
18	//!   resolution).
19	
20	use std::error::Error;
21	use std::path::{Path, PathBuf};
22	
23	use clap::Args;
24	
25	use log::{info, warn};
26	
27	use crate::common::{bot_repo_path, configured_bot_dir, find_workspace_root, reject_legacy_config};
28	use crate::config_schema::{ConfigKey, Home, render_key_block, schema, section_and_leaf};
29	use crate::context::Context;
30	use crate::desc_helpers::VC_CONFIG_FILE;
31	use crate::options_flags::scope::{Scope, Side, parse_scope};
32	use crate::subcommand::SubcommandRunner;
33	
34	/// Parsed positional target: a side keyword set or an explicit
35	/// config-file path.
36	///
37	/// - `Scope`: `work`, `bot`, `work,bot`, `bot,work` (the `--scope`
38	///   grammar), resolved against the surrounding workspace.
39	/// - `Path`: anything else, an explicit config file. The only way
40	///   to reach the user config.
41	#[derive(Clone, Debug, PartialEq)]
42	pub enum ConfigTarget {
43	    Scope(Scope),
44	    Path(PathBuf),
45	}
46	
47	/// Parse the positional target: side keyword form first, else a
48	/// path.
49	///
50	/// A file literally named `work` (etc.) in cwd is shadowed by the
51	/// keyword: target it as `./work`.
52	fn parse_target(s: &str) -> Result<ConfigTarget, String> {
53	    if let Ok(scope) = parse_scope(s) {
54	        return Ok(ConfigTarget::Scope(scope));
55	    }
56	    if s.is_empty() {
57	        return Err("config: target is empty".into());
58	    }
59	    Ok(ConfigTarget::Path(PathBuf::from(s)))
60	}
61	
62	#[derive(Args, Debug)]
63	pub struct ConfigArgs {
64	    /// What to print or validate: side keyword(s) `work`, `bot`,
65	    /// `work,bot`, or a config-file path. The user config
66	    /// (`~/.config/vc-x1/config.toml`) has no keyword: pass its
67	    /// path.
68	    #[arg(value_parser = parse_target, default_value = "work,bot", verbatim_doc_comment)]
69	    pub target: ConfigTarget,
70	
71	    /// Check the target config file(s) (unknown/misspelled keys,
72	    /// legacy-schema rejection, [repos] resolved-agreement
73	    /// invariant) instead of printing the schema
74	    #[arg(long)]
75	    pub validate: bool,
76	}
77	
78	/// Inputs to the `config` op, flat, owned, clap-free.
79	///
80	/// Mirrors `ConfigArgs`: positional target (`target`), `--validate`
81	/// (`validate`).
82	pub struct ConfigParams {
83	    pub target: ConfigTarget,
84	    pub validate: bool,
85	}
86	
87	impl From<&ConfigArgs> for ConfigParams {
88	    /// Convert clap-derived `ConfigArgs` into the flat
89	    /// `ConfigParams` (total: every field copies straight over).
90	    fn from(a: &ConfigArgs) -> Self {
91	        Self {
92	            target: a.target.clone(),
93	            validate: a.validate,
94	        }
95	    }
96	}
97	
98	impl SubcommandRunner for ConfigArgs {
