160	/// True if `actual` (a config key from a loaded config file) is
161	/// recognized by some `schema()` entry whose homes satisfy
162	/// `home_pred`.
163	///
164	/// - Non-dynamic entries match by exact path equality.
165	/// - Dynamic entries (`key.dynamic`) match segment-wise: equal
166	///   segment counts, each entry segment either equal to the actual
167	///   segment or a `<placeholder>` matching any single segment.
168	fn key_known(actual: &str, home_pred: fn(&[Home]) -> bool) -> bool {
169	    schema().iter().any(|key| {
170	        if !home_pred(key.homes) {
171	            return false;
172	        }
173	        if !key.dynamic {
174	            return key.path == actual;
175	        }
176	        let entry_segs: Vec<&str> = key.path.split('.').collect();
177	        let actual_segs: Vec<&str> = actual.split('.').collect();
178	        entry_segs.len() == actual_segs.len()
179	            && entry_segs
180	                .iter()
181	                .zip(actual_segs.iter())
182	                .all(|(e, a)| e == a || (e.starts_with('<') && e.ends_with('>')))
183	    })
184	}
