190	///   and returns `Ok(0)`.
191	/// - Each key not recognized by `key_known` is reported with
192	///   `warn!`, naming `label` and the key; keys are checked in
193	///   sorted order for stable output.
194	/// - Returns the count of unknown keys found. A load error
195	///   (malformed TOML) propagates as `Err`.
196	fn validate_file(
197	    path: &Path,
198	    label: &str,
199	    home_pred: fn(&[Home]) -> bool,
200	) -> Result<usize, Box<dyn Error>> {
201	    if !path.exists() {
202	        info!("{label}: {} not found, skipping", path.display());
203	        return Ok(0);
204	    }
205	    let map = crate::config_md::load_file(path)?;
206	    let mut keys: Vec<&String> = map.keys().collect();
207	    keys.sort();
208	
209	    let mut unknown = 0;
210	    for key in keys {
211	        if !key_known(key, home_pred) {
212	            warn!("{label} ({}): unknown key {key:?}", path.display());
213	            unknown += 1;
214	        }
215	    }
216	    Ok(unknown)
217	}
