1	//! Markdown-carried instance config: the md -> toml filter and the
2	//! resolver/loader every `.vc-config.*` reader goes through.
3	//!
4	//! The format: a config file is a markdown document whose `toml`
5	//! fences, concatenated in document order, form the TOML the loader
6	//! parses. Prose between fences is documentation (doc one-liners,
7	//! reference links) and never reaches the parser. One rule falls
8	//! out for authors: a `[table]` header captures every key after it
9	//! until the next header, so a table's keys must stay in its
10	//! stretch of the document.
11	//!
12	//! `.vc-config.toml` remains a valid carrier through the family's
13	//! migration window; a side holding both carriers is an error.
14	
15	use std::collections::HashMap;
16	use std::path::{Path, PathBuf};
17	
18	use crate::desc_helpers::VC_CONFIG_FILE;
19	use crate::toml_simple;
20	
21	/// The markdown instance-config filename (the toml carrier's name
22	/// is [`VC_CONFIG_FILE`]).
23	pub const VC_CONFIG_MD: &str = ".vc-config.md";
24	
25	/// What the filter is inside of, line by line.
26	enum Fence {
27	    /// Outside any fence: prose, blanked.
28	    None,
29	    /// Inside a ```toml fence: lines pass through.
30	    Toml,
31	    /// Inside any other fence (illustration idiom): blanked.
32	    Other,
33	}
34	
35	/// Extract the TOML a config markdown document carries.
36	///
37	/// - `toml`-tagged fence interiors pass through verbatim.
38	/// - Every other line (prose, fence markers, other fences'
39	///   interiors) is blanked rather than removed, so the result has
40	///   the source's line count and any parse diagnostic points at
41	///   the real line.
42	/// - The tag must be exactly `toml` (` ```toml `); a fence tagged
43	///   otherwise or untagged is illustration and is ignored.
44	/// - An unclosed fence is an error naming its opening line.
45	pub fn md_to_toml(content: &str) -> Result<String, String> {
46	    let mut state = Fence::None;
47	    let mut opened_at = 0usize;
48	    let mut out = String::with_capacity(content.len());
49	    for (idx, line) in content.lines().enumerate() {
50	        let trimmed = line.trim_start();
51	        match state {
52	            Fence::None => {
53	                if let Some(info) = trimmed.strip_prefix("```") {
54	                    state = if info.trim() == "toml" {
55	                        Fence::Toml
56	                    } else {
57	                        Fence::Other
58	                    };
59	                    opened_at = idx + 1;
60	                }
61	            }
62	            Fence::Toml => {
63	                if is_fence_close(trimmed) {
64	                    state = Fence::None;
65	                } else {
66	                    out.push_str(line);
67	                }
68	            }
69	            Fence::Other => {
70	                if is_fence_close(trimmed) {
71	                    state = Fence::None;
72	                }
73	            }
74	        }
75	        out.push('\n');
76	    }
77	    if matches!(state, Fence::None) {
78	        Ok(out)
79	    } else {
80	        Err(format!("unclosed fence opened at line {opened_at}"))
81	    }
82	}
83	
84	/// True when a (trim_start'ed) line closes a fence: backticks with
85	/// nothing but whitespace after them.
86	fn is_fence_close(trimmed: &str) -> bool {
87	    trimmed
88	        .strip_prefix("```")
89	        .is_some_and(|rest| rest.trim().is_empty())
90	}
91	
92	/// Resolve which instance-config file `dir` holds.
93	///
94	/// `Ok(None)` when neither carrier exists. Holding both is an
95	/// error: two files that can disagree are no longer a config.
96	pub fn vc_config_path(dir: &Path) -> Result<Option<PathBuf>, String> {
97	    let md = dir.join(VC_CONFIG_MD);
98	    let toml = dir.join(VC_CONFIG_FILE);
99	    match (md.exists(), toml.exists()) {
100	        (true, true) => Err(format!(
101	            "{}: both {VC_CONFIG_MD} and {VC_CONFIG_FILE} exist: keep one \
102	             ({VC_CONFIG_MD} is the current carrier); nothing was changed",
103	            dir.display()
104	        )),
105	        (true, false) => Ok(Some(md)),
106	        (false, true) => Ok(Some(toml)),
107	        (false, false) => Ok(None),
108	    }
109	}
110	
111	/// Load one config file, whatever its carrier: a `.md` path runs
112	/// through [`md_to_toml`] first, anything else parses as plain
113	/// TOML.
114	pub fn load_file(path: &Path) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
115	    if path.extension().is_some_and(|e| e == "md") {
116	        let content = std::fs::read_to_string(path)
117	            .map_err(|e| format!("cannot read '{}': {e}", path.display()))?;
118	        let toml = md_to_toml(&content).map_err(|e| format!("{}: {e}", path.display()))?;
119	        Ok(toml_simple::toml_parse(&toml))
120	    } else {
121	        toml_simple::toml_load(path)
122	    }
123	}
124	
125	/// A loaded instance config: the file it came from (for messages)
126	/// and its flat key map.
127	pub struct VcConfig {
128	    pub path: PathBuf,
129	    pub map: HashMap<String, String>,
130	}
131	
132	/// Resolve and load `dir`'s instance config.
133	///
134	/// `Ok(None)` when the directory has no config file; an error is a
135	/// real problem (both carriers present, unreadable file, a bad
136	/// fence), never a plain miss.
137	pub fn load(dir: &Path) -> Result<Option<VcConfig>, Box<dyn std::error::Error>> {
138	    let Some(path) = vc_config_path(dir)? else {
139	        return Ok(None);
140	    };
141	    let map = load_file(&path)?;
142	    Ok(Some(VcConfig { path, map }))
143	}
